1	import {once} from 'node:events';
2	import {askOnOpen, connectClient, framesUntil, startEngine, stopEngines} from './wsTestSupport.js';
3	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
4	import type {SessionStore} from '../types/sessionStore.js';
5	
6	// A store that answers from a database cannot answer in the same tick, so the handler must wait without dropping a frame.
7	
8	const CREATE_MS = 50;
9	// A hang fails in this long instead of stalling the suite; its tests stay on one line so a spec citation can name them.
10	const FAIL_FAST_MS = 5_000;
11	const wait = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));
12	
13	// Wraps the real store so only the timing of `create` differs from the shipped one.
14	const slowStore = (delayMs: number, failWith?: Error): SessionStore => {
15	  const store = new InMemorySessionStore();
16	  return Object.assign(Object.create(Object.getPrototypeOf(store) as object) as SessionStore, store, {
17	    create: async (sessionId: string, userId: string | number) => {
18	      await wait(delayMs);
19	      if (failWith) throw failWith;
20	      return store.create(sessionId, userId);
21	    },
22	    get: (sessionId: string) => store.get(sessionId),
23	    delete: (sessionId: string) => store.delete(sessionId),
24	    count: () => store.count(),
25	    clear: () => store.clear(),
26	  }) as SessionStore;
27	};
28	
29	describe('awaiting a slow session store', () => {
30	  afterEach(stopEngines);
31	
32	  // prettier-ignore
33	  it('delivers a frame sent before the connected frame arrives', async () => {
34	    const url = await startEngine(slowStore(CREATE_MS));
35	    const {finished} = askOnOpen(url);
36	
37	    const seen = await finished;
38	
39	    expect(seen[0]).toBe('connected');
40	  }, FAIL_FAST_MS);
41	
42	  it('leaves no session behind when the socket closes during create', async () => {
43	    const store = slowStore(CREATE_MS);
44	    const url = await startEngine(store);
45	    const client = connectClient(url);
46	    await once(client, 'open');
47	
48	    client.terminate();
49	    await wait(CREATE_MS * 3);
50	    const held = await store.count();
51	
52	    expect(held).toBe(0);
53	  });
54	
55	  // prettier-ignore
56	  it('answers a rejecting create with SERVER_ERROR rather than an unhandled rejection', async () => {
57	    const unhandled: unknown[] = [];
58	    const record = (reason: unknown) => void unhandled.push(reason);
59	    process.on('unhandledRejection', record);
60	    const url = await startEngine(slowStore(1, new Error('store down')));
61	    const client = connectClient(url);
62	    const failed = framesUntil(client, 'error');
63	
64	    const seen = await failed;
65	    await wait(20);
66	    process.off('unhandledRejection', record);
67	
68	    expect({seen, unhandled: unhandled.length}).toEqual({seen: ['error'], unhandled: 0});
69	  }, FAIL_FAST_MS);
70	});
